#!/usr/bin/env bash
set -eu

awk '
{
    ip = $1
    count[ip]++
    if (!(ip in first)) {
        first[ip] = ++n
        order[n] = ip
    }
}
END {
    for (i = 1; i <= n; i++) ip = order[i]
    # stable insertion sort of order[1..n] by count desc, first appearance asc
    for (i = 2; i <= n; i++) {
        ip = order[i]
        j = i - 1
        while (j >= 1 && (count[order[j]] < count[ip] || \
               (count[order[j]] == count[ip] && first[order[j]] > first[ip]))) {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = ip
    }
    for (i = 1; i <= n && i <= 3; i++) print order[i]
}
